import React from 'react'
import "./header.css"

const Header = () => {
  return (
    <header className="header">
      <nav className="nav container">
        <a href="index.html" className="nav-logo">Sudeshna</a>

        <div className="nav-menu"></div>
      </nav>
    </header>
  )
}

export default Header
